def note(id,title,body,lesson,questions,source,preliminary=False):
 n={'id':id,'title':title,'source':source,'text':f'# {title}\nLiterature and Environment · Semester 4\n\n{body}\n\n## Classroom lesson · 50 minutes\n{lesson}\n\n## Questions\n{questions}\n\nTeaching draft: consult the assigned edition or film and check claims before teaching.'}
 if preliminary:n['status']='preliminary'
 return n
